  ui_story_30110601_98_dialog_content = "Lumópolis?! Mas você não sempre esteve...",
  ui_story_30110601_99_dialog_content = "Contra as teimosas e antigas maneiras de Lumópolis?",
  ui_story_30110601_100_dialog_content = "Se for assim, por que você escolheria vir para cá? Este lugar... se eu estou certo, é um cemitério para a nobreza de Lumópolis.",
  ui_story_30110601_101_dialog_content = "...",
  ui_story_30110601_102_dialog_content = "Honestamente, achei que você já teria usado seus poderes para descobrir a verdade até agora, Celestita.",
