  ui_story_30110601_110_dialog_content = "Eles nem sequer tiveram a misericórdia de serem enterrados em seu próprio cemitério. Tudo o que podiam fazer era implorar às famílias mais simpáticas para ajudá-los em segredo...",
  ui_story_30110601_111_dialog_content = "...E assim, eles foram enterrados aqui.",
  ui_story_30110601_112_dialog_content = "Que irônico...",
  ui_story_30110601_113_dialog_content = "Os ancestrais da Família Kartima sacrificaram seu sangue e vidas para proteger Lumópolis, mas agora... Eles foram praticamente esquecidos pelo povo.",
  ui_story_30110601_114_dialog_content = "O império esqueceu que sua glória atual foi construída sobre o sangue dos dragões.",
  ui_story_30110601_115_dialog_content = "A Noite Branca lá no alto...",
  ui_story_30110601_116_dialog_content = "Mas sangue e ossos abaixo.",
  ui_story_30110601_117_dialog_content = "Sinto muito...",
  ui_story_30110601_118_dialog_content = "Eu não queria me intrometer...",
  ui_story_30110601_119_dialog_content = "Por favor, aceite minhas desculpas, Sharona... Você e sua família.",
  ui_story_30110601_120_dialog_content = "Como um estranho, eu perturbei o sono deles.",
  ui_story_30110601_121_dialog_content = "...",
  ui_story_30110601_122_dialog_content = "Eles não são minha família.",
  ui_story_30110601_123_dialog_content = "Mas seu nome...",
  ui_story_30110601_124_dialog_content = "Você realmente acha que somos uma família só porque compartilhamos um sobrenome?",
  ui_story_30110601_125_dialog_content = "Sharona Kartima...",
  ui_story_30110601_126_dialog_content = "Eles são meus clãs, mas não são minha família.",
  ui_story_30110601_127_dialog_content = "Eles não têm como me contar a verdade sobre a morte dos meus pais, e eu não posso fingir que de alguma forma, não estou conectado a eles.",
  ui_story_30110601_128_dialog_content = "Seus pais...",
  ui_story_30110601_129_dialog_content = "Eu nem me lembro mais deles.",
  ui_story_30110601_130_dialog_content = "Quando se trata da Família Kartima, a coisa que me deixou a impressão mais profunda...",
  ui_story_30110601_131_dialog_content = "Aconteceu no dia do <color=#FFB400>genocídio</color>.",
  ui_story_30110601_132_dialog_content = "Logo antes de morrer, um ancião muito respeitado na família me disse...",
  ui_story_30110601_133_dialog_content = "Lembre-se sempre do meu nome e nunca desista da busca pelo <color=#FFB400>segredo</color> da minha linhagem.",
  ui_story_30110601_134_dialog_content = "Antes disso, eu nem merecia cumprimentar o homem em reuniões de família.",
  ui_story_30110601_135_dialog_content = "Então... você já descobriu o segredo da sua linhagem?",
  ui_story_30110601_136_dialog_content = "Procurei por muito, muito tempo, mas... ainda não encontrei a resposta.",
  ui_story_30110601_137_dialog_content = "Nem sei por que me confiaram essa tarefa impossível em primeiro lugar.",
  ui_story_30110601_138_dialog_content = "Só porque sou o último membro sobrevivente da nossa família, espera-se que eu carregue o fardo da história secreta da nossa linhagem?",
  ui_story_30110601_139_dialog_content = "Fragmentos do passado constantemente surgem em minha mente, trazendo um fluxo interminável de ódio...",
  ui_story_30110601_140_dialog_content = "...Isso não é justo.",
  ui_story_30110601_141_dialog_content = "Sinto muito...",
  ui_story_30110601_142_dialog_content = "Eu realmente não quis perguntar sobre você e o passado do seu clã...",
  ui_story_30110601_143_dialog_content = "Se você não tivesse me trazido aqui, nunca teria sabido.",
  ui_story_30110601_144_dialog_content = "Sim...",
  ui_story_30110601_145_dialog_content = "Espere... Família! Isso mesmo!",
  ui_story_30110601_146_dialog_content = "Ilumina! A Federação Illumina!",
  ui_story_30110601_147_option_content = "Eles são seu verdadeiro lar, não são, Sharona?",
  ui_story_30110601_148_dialog_content = "...Minha casa?",
  ui_story_30110601_149_dialog_content = "Lar é um lugar que me ama incondicionalmente e não pede nada em troca.",
  ui_story_30110601_150_dialog_content = "Minha relação com a Illumina... Foi construída na confiança do Grande Marechal.",
  ui_story_30110601_151_option_content = "Não, a Illumina também não conta...",
  ui_story_30110601_152_dialog_content = "Eu concordo, na maior parte.",
  ui_story_30110601_153_dialog_content = "O significado de lar é muito mais profundo.",
  ui_story_30110601_154_dialog_content = "Uma casa proporciona um profundo e inseparável sentimento de amor...",
  ui_story_30110601_155_dialog_content = "Enquanto na Illumina, eu trabalho apenas para corresponder à confiança e às expectativas dos outros.",
  ui_story_30110601_156_dialog_content = "Embora, em troca, me seja concedido um poder considerável...",
  ui_story_30110601_157_dialog_content = "Às vezes, me pego dizendo... Que talvez este lugar seja minha casa.",
  ui_story_30110601_158_dialog_content = "(O que realmente significa casa...?)",
  ui_story_30110601_159_dialog_content = "(Eu nunca morei em Eraveil, mas...)",
  ui_story_30110601_160_dialog_content = "(Posso dizer, com total certeza, que Eraveil é minha casa.)",
  ui_story_30110601_161_dialog_content = "(E Soroz... Ele não é apenas meu abrigo, mas também meu amigo. Eu nunca estive realmente sozinho enquanto crescia...)",
  ui_story_30110601_162_dialog_content = "(E eu fiz todos os tipos de amigos desde então.)",
  ui_story_30110601_163_dialog_content = "(Mas para Sharona... Onde seria o lar dela?)",
  ui_story_30110601_164_dialog_content = "(Nunca cheguei a conhecer nenhum dos meus parentes, mas tenho certeza de que o amor deles por mim era real.)",
  ui_story_30110601_165_dialog_content = "(Sharona cresceu cercado pela família, mas ainda não sabe onde é o lar...)",
  ui_story_30110601_166_dialog_content = "Falei demais.",
  ui_story_30110601_167_dialog_content = "Obrigado pela sua ajuda, Celestita.",
  ui_story_30110601_168_dialog_content = "Sem problemas.",
  ui_story_30110601_169_dialog_content = "Tenho certeza que tudo isso deve estar te confundindo.",
  ui_story_30110601_170_dialog_content = "Afinal, por que eu estaria aqui prestando meus respeitos se eles não fossem minha família?",
  ui_story_30110601_171_dialog_content = "Acho que... Você está tentando descobrir o que aconteceu no passado, certo?",
  ui_story_30110601_172_option_content = "A verdade por trás do seu clã?",
  ui_story_30110601_173_dialog_content = "Sim.",
  ui_story_30110601_174_dialog_content = "Assim como nossa conexão com os dragões.",
  ui_story_30110601_175_dialog_content = "Os fragmentos gritantes das minhas memórias... de verdadeiros dragões.",
  ui_story_30110601_176_option_content = "O segredo da sua linhagem?",
  ui_story_30110601_177_dialog_content = "Sim.",
  ui_story_30110601_178_dialog_content = "Talvez depois que eu descobrir os segredos da Família Kartima...",
  ui_story_30110601_179_dialog_content = "A verdade por trás do passado, e a resposta para os fragmentos de ódio em minha mente... Talvez tudo seja revelado então.",
  ui_story_30110601_180_dialog_content = "Mas até eu descobrir a verdade por trás de tudo isso...",
  ui_story_30110601_181_dialog_content = "Tudo que posso fazer é vir aqui para prestar minhas homenagens todos os anos, na esperança de sentir algo...",
  ui_story_30110601_182_dialog_content = "Porque compartilhamos um sobrenome, eu nunca estou realmente sozinho.",
  ui_story_30110601_183_dialog_content = "Mesmo se... Eu não os considero minha família.",
  ui_story_30110601_184_dialog_content = "(Família...)",
  ui_story_30110601_185_dialog_content = "Eu...",
  ui_story_30110601_186_dialog_content = "Sharona... Por favor, ofereça meus respeitos a eles em meu lugar.",
  ui_story_30110601_187_dialog_content = "Vamos.",
  ui_story_30110601_188_dialog_content = "Antes de irmos... Há algo que preciso perguntar a você.",
  ui_story_30110601_189_dialog_content = "Claro.",
  ui_story_30110601_190_dialog_content = "Celestita... Peço que você se abstenha de divulgar a localização deste lugar para qualquer outra pessoa.",
  ui_story_30110601_191_dialog_content = "Até onde eu entendo o povo de Lumópolis...",
  ui_story_30110601_192_dialog_content = "Eles são rápidos para esquecer a gentileza, mas nunca esquecerão um rancor.",
  ui_story_30110601_193_dialog_content = "Especialmente não um rancor contra a traiçoeira Família Kartima...",
  ui_story_30110601_194_dialog_content = "O ódio deles nunca vai realmente desaparecer.",
  ui_story_30110601_195_dialog_content = "Isso, eu temo, é a única coisa que tenho em comum com o povo de Lumópolis.",
  ui_story_30110601_196_dialog_content = "Está sempre lá... A sensação familiar de ódio, constantemente fazendo meu sangue ferver...",
  ui_story_30110601_197_dialog_content = "Eu prometo.",
  ui_story_30110601_198_dialog_content = "Que momento tocante...",
  ui_story_30110601_199_dialog_content = "Se realmente foi tão emocionante, então por que você não está chorando?",
  ui_story_30110601_200_dialog_content = "Chorar? Por que eu choraria?",
  ui_story_30110601_201_dialog_content = "Não me faça rir.",
  ui_story_30110601_202_dialog_content = "...Você está atrasado, Leona.",
  ui_story_30110601_203_dialog_content = "Atrasado? Eles não são dignos da minha visita, muito menos da minha pontualidade.",
  ui_story_30110601_204_dialog_content = "Essa sua roupa...",
  ui_story_30110601_205_dialog_content = "Ainda tentando seguir suas <color=#FFB400>tradições</color> há muito mortas, Sharona?",
  ui_story_30110601_206_dialog_content = "Ninguém no mundo além de mim reconhece essa roupa como o traje formal da Família Kartima.",
  ui_story_30110601_207_dialog_content = "Então, enquanto estivermos vivos, e eu tiver essa roupa...",
  ui_story_30110601_208_dialog_content = "A Família Kartima não foi completamente abandonada pela história.",
  ui_story_30110601_209_dialog_content = "Hmph... Quanta inocência.",
  ui_story_30110601_210_dialog_content = "Qual o sentido dessas formalidades e homenagens, se estamos fadados a repetir os mesmos erros?",
  ui_story_30110601_211_dialog_content = "Mas você já sabe disso muito bem, não é... irmãzinha?",
  ui_story_30110601_212_dialog_content = "Não há como escapar deste destino. Um dia, também estaremos deitados, frios e mortos neste lugar.",
  ui_story_30110601_213_dialog_content = "A única diferença é que, quando partirmos, ninguém estará lá para vestir essas roupas e prestar homenagens a nós.",
  ui_story_30110601_214_dialog_content = "...Isso não importa.",
  ui_story_30110601_215_dialog_content = "Oh, querida irmã... seu entendimento do destino é tão lamentavelmente superficial.",
  ui_story_30110601_216_dialog_content = "Mas eu acho...",
  ui_story_30110601_217_dialog_content = "Há alguém aqui com uma compreensão muito mais profunda da palavra destino...",
  ui_story_30110601_218_dialog_content = "Não é verdade... O solitário Celestita?",
  ui_story_30110601_219_dialog_content = "...Eu?",
  ui_story_30110601_220_dialog_content = "Eu não estou sozinho de jeito nenhum!",
  ui_story_30110601_221_dialog_content = "É mesmo, kiddo? Eu invejo sua confiança.",
  ui_story_30110601_222_dialog_content = "Eu só espero que você nunca pare de se sentir assim...",
  ui_story_30110601_223_dialog_content = "Agora, meus queridos. Eu tenho que dizer adeus.",
  ui_story_30110601_224_dialog_content = "Ela entrou, Sharona...",
  ui_story_30110601_225_dialog_content = "...",
  ui_story_30110601_226_dialog_content = "Sharona? Sharona!",
  ui_story_30110601_227_dialog_content = "...Vamos lá.",
  ui_story_30110601_228_dialog_content = "De volta para... Illumina.",
  ui_story_30110601_229_dialog_content = "...Claro. Vamos voltar juntos.",
  ui_story_30110601_230_dialog_content = "<color=#e8d9bb>No dia seguinte.</color>",
  ui_story_30110601_231_dialog_content = "Navegador? Ei, Navegador! Você está se sentindo bem?",
  ui_story_30110601_232_dialog_content = "Uh... Ahn?",
  ui_story_30110601_233_dialog_content = "O que está passando pela sua cabeça? Precisa de um pouco de ar fresco? Vamos, vamos dar uma volta pela Cidade Gannon!",
  ui_story_30110601_234_dialog_content = "N-Nada em minha mente, sério...",
  ui_story_30110601_235_dialog_content = "Ei, Vice... o que a palavra casa significa para você?",
  ui_story_30110601_236_dialog_content = "Huh? Se eu tivesse que dizer...",
  ui_story_30110601_237_dialog_content = "O Colossus é meu lar, e Illumina também.",
  ui_story_30110601_238_dialog_content = "Qualquer lugar onde eu possa viver confortavelmente é um lugar que posso chamar de lar.",
  ui_story_30110601_239_dialog_content = "Sim...",
  ui_story_30110601_240_dialog_content = "Um lugar confortável...",
  ui_story_30110601_241_dialog_content = "(Para Sharona, lar é um lugar para o qual ela sempre pode retornar. É onde ela pertence.",
  ui_story_30110601_242_dialog_content = "(Devotando-se a Illumina...)",
  ui_story_30110601_243_dialog_content = "(É a maneira dela de resistir ao destino e encontrar um lar.)",
  ui_story_30110601_244_dialog_content = "(Eu apenas me pergunto...)",
  ui_story_30110601_245_dialog_content = "(Se a Colossus algum dia se sentirá como um lar para ela?)",
  ui_story_30110602_1_dialog_content = "De acordo com as coordenadas, este deve ser o lugar. Mas...",
  ui_story_30110602_2_dialog_content = "O Sharona realmente está atrasado?",
  ui_story_30110602_3_dialog_content = "Mesmo que seja esse o caso, a maioria das tropas de Illumina já deveria estar aqui agora...",
  ui_story_30110602_4_dialog_content = "Não deveria estar tão silencioso por aqui.",
  ui_story_30110602_5_dialog_content = "Será que... Eu errei o local?",
  ui_story_30110602_6_dialog_content = "Se eu me atrasar por causa de um erro estúpido como esse, Sharona vai ficar furioso. Eu é melhor...",
  ui_story_30110602_7_dialog_content = "Não, você está no lugar certo, PlayerName.",
  ui_story_30110602_8_dialog_content = "!",
  ui_story_30110602_9_dialog_content = "Comandante Sharona? Quase não te reconheci! Então você estava aqui o tempo todo...",
  ui_story_30110602_10_dialog_content = "Você, uh...",
  ui_story_30110602_11_dialog_content = "Pare de fazer rodeios. Se você tem perguntas, apenas me pergunte logo.",
  ui_story_30110602_12_dialog_content = "Por que você está sozinho? Onde está o resto da Legião Illumina? E... O que há com essas roupas?",
  ui_story_30110602_13_dialog_content = "Vou responder suas perguntas uma de cada vez.",
  ui_story_30110602_14_dialog_content = "Primeiro, esta é uma missão privada, que não envolve o exército da Federação Illumina.",
  ui_story_30110602_15_dialog_content = "Em segundo lugar, preparei essas roupas especificamente para essa missão.",
  ui_story_30110602_16_dialog_content = "Roupas especiais para uma missão privada, hein? Bem, elas parecem incrivelmente caras.",
  ui_story_30110602_17_dialog_content = "Na verdade, eles parecem um pouco deslocados aqui.",
  ui_story_30110602_18_dialog_content = "Eles têm algo a ver com essas ruínas brancas?",
  ui_story_30110602_19_dialog_content = "Muito perspicaz, PlayerName.",
  ui_story_30110602_20_dialog_content = "Recentemente, me deparei com um grupo de pessoas de aparência suspeita. Eles adoram regularmente um ídolo de dragão próximo.",
  ui_story_30110602_21_dialog_content = "Presumo que eles sejam provavelmente um grupo de cultistas malignos... ou os remanescentes de uma facção traidora.",
  ui_story_30110602_22_dialog_content = "Isso significa...",
  ui_story_30110602_23_dialog_content = "Suspeito que eles estejam de alguma forma conectados à Casa Kartima, sim.",
  ui_story_30110602_24_dialog_content = "Então essas roupas pertencem à Casa Kartima?",
  ui_story_30110602_25_dialog_content = "De maneira nenhuma. Isso é simplesmente um disfarce usado para se infiltrar em suas fileiras.",
  ui_story_30110602_26_dialog_content = "Escolhi essas roupas para combinar com as que vi eles usando durante o culto.",
  ui_story_30110602_27_dialog_content = "Sério? Mas parece que foram feitos sob medida apenas para você.",
  ui_story_30110602_28_dialog_content = "Com uma roupa tão pura e digna como esta, eles podem até pensar que você é um santo ou algo assim.",
  ui_story_30110602_29_dialog_content = "Isso não é importante agora, PlayerName.",
  ui_story_30110602_30_dialog_content = "Tudo o que importa é que eu consegui usar esse disfarce para me infiltrar e derrotá-los.",
  ui_story_30110602_31_dialog_content = "A cena já foi limpa de quaisquer sinais de batalha, é por isso que eu te convidei para cá.",
  ui_story_30110602_32_dialog_content = "Alguém tão versado em história antiga quanto você deveria ser capaz de dizer se essas ruínas estão ligadas à Casa Kartima ou aos dragões, certo?",
  ui_story_30110602_33_dialog_content = "Certamente vou tentar o meu melhor.",
  ui_story_30110602_34_dialog_content = "Mas... Não seria mais fácil simplesmente perguntar às pessoas que você prendeu?",
  ui_story_30110602_35_dialog_content = "... Eu tentei, mas apenas um deles ainda estava consciente após a batalha, e ele desmaiou assim que comecei a questioná-lo.",
  ui_story_30110602_36_dialog_content = "Isso não é surpreendente... Eu quase posso visualizar a batalha na minha mente...",
  ui_story_30110602_37_dialog_content = "Além disso, eles continuaram falando bobagens durante nossa luta. Algo me dizia que eu não conseguiria nada útil deles tão cedo.",
  ui_story_30110602_38_dialog_content = "É por isso que decidi pedir sua ajuda.",
  ui_story_30110602_39_dialog_content = "Entendi. Não se preocupe, eu tenho isso.",
  ui_story_30110602_40_dialog_content = "<color=#e8d9bb>Depois de um tempo...</color>",
  ui_story_30110602_41_dialog_content = "Ufa... Acho que descobri a maior parte agora.",
  ui_story_30110602_42_dialog_content = "A resposta pode ser um pouco decepcionante, porém. Este lugar não tem nada a ver com a Casa Kartima.",
  ui_story_30110602_43_dialog_content = "... É assim mesmo?",
  ui_story_30110602_44_dialog_content = "Então, por que eles estariam adorando aqui?",
  ui_story_30110602_45_dialog_content = "Parece que eles estão orando para um poder superior maligno. Julgando pelas evidências espalhadas por aqui...",
  ui_story_30110602_46_dialog_content = "É possível que eles vejam o ídolo do dragão como uma espécie de Eclipsite poderoso.",
  ui_story_30110602_47_dialog_content = "Afinal, não são muitas pessoas que viram um dragão de verdade nos dias de hoje.",
  ui_story_30110602_48_dialog_content = "Entendi. Eu deveria ter sabido melhor do que criar expectativas.",
  ui_story_30110602_49_dialog_content = "O homem que mencionei antes, aquele que desmaiou de medo durante o meu interrogatório... Havia uma razão para isso.",
  ui_story_30110602_50_dialog_content = "Durante a nossa batalha anterior...",
  ui_story_30110602_51_dialog_content = "O que houve?",
  ui_story_30110602_52_dialog_content = "Fiquei tão empolgado que quase perdi a razão.",
  ui_story_30110602_53_dialog_content = "A perspectiva de eles terem laços com minha família e a rebelião tornou impossível para mim controlar minhas emoções.",
  ui_story_30110602_54_dialog_content = "Os gritos deles estavam cheios de terror enquanto tentavam desesperadamente me manter longe...",
  ui_story_30110602_55_dialog_content = "Honestamente, eu detesto essa parte de mim mesmo.",
  ui_story_30110602_56_dialog_content = "Mas você recuperou o controle no final, não foi?",
  ui_story_30110602_57_dialog_content = "Eu fiz, mas apenas de má vontade. A verdade é—",
  ui_story_30110602_58_dialog_content = "Só recuperei o controle porque pensei que você poderia me dar mais respostas, PlayerName.",
  ui_story_30110602_59_dialog_content = "Mas o meu ódio por Lumopolis e minha família... assim como o meu próprio poder—",
  ui_story_30110602_60_dialog_content = "Pode chegar um dia em que isso me faça perder completamente o controle.",
  ui_story_30110602_61_dialog_content = "É possível que minha alma já tenha se entregado à violência há muito tempo.",
  ui_story_30110602_62_dialog_content = "Se ao menos eu pudesse saber o que meus ancestrais pensavam sobre esse poder.",
  ui_story_30110602_63_dialog_content = "(Então é por isso que ela queria saber se essas ruínas tinham algo a ver com a família dela...)",
  ui_story_30110602_64_dialog_content = "Bem... pelo que eu entendi, você realmente conseguiu derrubar um grupo de cultistas malignos.",
  ui_story_30110602_65_dialog_content = "Se você não os tivesse parado, quem sabe que tipo de problemas eles poderiam ter causado.",
  ui_story_30110602_66_dialog_content = "Isso é uma grande vitória no meu livro. Você não concorda?",
  ui_story_30110602_67_dialog_content = "Mas eu só fiz isso por puro interesse próprio.",
  ui_story_30110602_68_dialog_content = "Eu não iria tão longe, Sharona.",
  ui_story_30110602_69_dialog_content = "Se você realmente estivesse apenas interessado em aprender sobre os laços deles com a Casa Kartima, poderia facilmente ter evitado lutar contra eles.",
  ui_story_30110602_70_dialog_content = "Mas você viu o grupo deles como uma ameaça para Illumina e outros, então você agiu de maneira decisiva e os derrubou.",
  ui_story_30110602_71_dialog_content = "No final do dia, você ainda quer usar seu poder para proteger os outros, certo?",
  ui_story_30110602_72_dialog_content = "Mas... Um poder destrutivo como o meu realmente pode ser usado para proteger as pessoas?",
  ui_story_30110602_73_dialog_content = "Pode sim! O fato de a Casa Kartima ter existido após todo esse tempo é a prova disso.",
  ui_story_30110602_74_dialog_content = "Tenho certeza de que seus ancestrais usaram seu poder para proteger aqueles que eram importantes para eles no passado também.",
  ui_story_30110602_75_dialog_content = "Também tenho certeza de que você herdou o dever deles e usará seu próprio poder para proteger a Illumina e as pessoas que você se importa.",
  ui_story_30110602_76_dialog_content = "Eu realmente tenho o direito de fazer isso?",
  ui_story_30110602_77_dialog_content = "Claro que sim, Sharona! Eu vi o quão forte você é, mas também vi o quão gentil você pode ser.",
  ui_story_30110602_78_dialog_content = "Se alguém pode fazer isso, é você!",
  ui_story_30110602_79_dialog_content = "...",
  ui_story_30110602_80_dialog_content = "Obrigado, PlayerName. Sempre fui grato pela sua orientação constante.",
  ui_story_30110602_81_dialog_content = "Às vezes eu me pergunto como seria minha vida se eu tivesse alguém como você na minha família.",
  ui_story_30110602_82_dialog_content = "Eu me tornaria tão selvagem se fosse esse o caso?",
  ui_story_30110602_83_dialog_content = "Família...",
  ui_story_30110602_84_dialog_content = "(Sharona mencionou algo sobre isso antes...)",
  ui_story_30110602_85_dialog_content = "Lar é um lugar que me ama incondicionalmente e não pede nada em troca.",
  ui_story_30110602_86_dialog_content = "(Se ela realmente não vê Illumina como um lugar que pode chamar de lar, então...)",
  ui_story_30110602_87_option_content = "Por que não fazer do Colossus a sua casa?",
  ui_story_30110602_88_dialog_content = "O Colossus? Bem, ele realmente tem uma certa sensação de lar.",
  ui_story_30110602_89_dialog_content = "Você e seus amigos moram lá, e todos parecem vê-lo como um lugar onde são sempre bem-vindos.",
  ui_story_30110602_90_dialog_content = "Mas... Por favor, perdoe minha indiscrição e esqueça qualquer coisa que eu disse sobre o assunto.",
  ui_story_30110602_91_option_content = "Quer que eu faça parte da sua família?",
  ui_story_30110602_92_dialog_content = "Ah... Me desculpe, PlayerName, eu estava apenas falando comigo mesmo agora.",
  ui_story_30110602_93_dialog_content = "Por favor, me perdoe por expressar esses pensamentos inúteis e fazer você se preocupar.",
  ui_story_30110602_94_dialog_content = "Tente não pensar muito nisso. Não foi nada mais do que uma reclamação casual.",
  ui_story_30110602_95_dialog_content = "Eu estava falando sério.",
  ui_story_30110602_96_dialog_content = "Você era?",
  ui_story_30110602_97_dialog_content = "Claro. Eu não ousaria fazer piadas na frente de um ídolo dragão, afinal.",
  ui_story_30110602_98_dialog_content = "Você uma vez me disse que Illumina não era realmente sua casa... Se você tiver interesse, acho que a Colossus é uma ótima escolha!",
  ui_story_30110602_99_dialog_content = "Você está sempre cuidando de mim, então quero fazer tudo o que posso para te ajudar também.",
  ui_story_30110602_100_dialog_content = "Pode ser um pouco arrogante da minha parte dizer isso, mas eu realmente espero que eu possa me tornar alguém em quem você possa confiar.",
  ui_story_30110602_101_dialog_content = "Afinal, você disse que pensou em mim pouco antes de perder o controle mais cedo, certo?",
  ui_story_30110602_102_dialog_content = "Se pensar em mim ajuda, então talvez algum dia você consiga transformar seu poder destrutivo—",
  ui_story_30110602_103_dialog_content = "—em poder para proteger algo importante?",
  ui_story_30110602_104_dialog_content = "Algo importante...",
  ui_story_30110602_105_dialog_content = "Não posso negar que você passou pela minha mente mais cedo, PlayerName.",
  ui_story_30110602_106_dialog_content = "Mas...",
  ui_story_30110602_107_dialog_content = "Ah, mas você não precisa tomar uma decisão agora ou algo assim!",
  ui_story_30110602_108_dialog_content = "Mesmo que seja presunçoso da minha parte perguntar, eu realmente espero que você leve isso em consideração, Sharona.",
  ui_story_30110602_109_dialog_content = "Por favor, não entenda mal, eu não estava tentando te chatear.",
  ui_story_30110602_110_dialog_content = "Mas a ideia de você se tornar parte da minha família...",
  ui_story_30110602_111_dialog_content = "Não tenho certeza se poderia aceitar isso... não como estou agora, de qualquer forma.",
  ui_story_30110602_112_dialog_content = "Eu talvez precise de mais tempo para me preparar.",
  ui_story_30110602_113_dialog_content = "Tome todo o tempo que precisar! Sempre que tiver um tempo livre, por que não vem visitar sua potencial nova casa?",
  ui_story_30110602_114_dialog_content = "Estou sempre aberto a sugestões, especialmente se isso fizer o Colossus se sentir mais como um lar para você.",
  ui_story_30110602_115_dialog_content = "Não será necessário.",
  ui_story_30110602_116_dialog_content = "Não faz diferença para mim se estou na Illumina ou a bordo do Colossus.",
  ui_story_30110602_117_dialog_content = "<size=30>Enquanto eu estiver ao seu lado...</size>",
